pub fn hstack(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    // Compute total length safely to avoid usize overflow.
    let total_len = a
        .len()
        .checked_add(b.len())
        .expect("hstack: length overflow");

    let mut out = Vec::with_capacity(total_len);

    // Do not mutate inputs; copy elements into a new vector.
    out.extend(a.iter().copied());
    out.extend(b.iter().copied());

    out
}

